={{ JSON.stringify({model: "home-chat", stream: false, temperature: 0, response_format: {
  "type": "json_schema",
  "json_schema": {
    "name": "pipeline_output",
    "strict": true,
    "schema": {
      "type": "object",
      "properties": {
        "themes": {
          "type": "array",
          "minItems": 1,
          "maxItems": 8,
          "items": {
            "type": "object",
            "properties": {
              "theme": {
                "type": "string"
              },
              "searchQuery": {
                "type": "string"
              },
              "rationale": {
                "type": "string"
              }
            },
            "required": [
              "theme",
              "searchQuery",
              "rationale"
            ],
            "additionalProperties": false
          }
        }
      },
      "required": [
        "themes"
      ],
      "additionalProperties": false
    }
  }
}, messages: [{ role: "system", content: "You prepare source themes for a weekly public technology and cybersecurity content brief. The input contains sanitized generic themes from private meetings. Consolidate duplicates and closely related ideas into five to eight broader public topics. Exclude personnel matters, emotional or performance assessments, client work, sales activity, pricing, contracts, procurement details, project-specific timelines, and anything that could expose an organization or individual. Prioritize enterprise technology, cybersecurity, AI governance, cloud, identity, infrastructure, observability, resilience, risk, compliance, and leadership decisions. Each search query must be generic, contain four to twelve useful words, and contain no company, customer, vendor, product, or person names. Every concept in the theme, query and rationale must be supported by the supplied themes. Do not add named frameworks, locations, dates, operational facts or inferred business context. Keep the rationale a brief explanation of grouping the supplied concepts; do not broaden it into new claims. Return only JSON that matches the supplied schema." }, { role: "user", content: "SANITIZED THEMES\n" + JSON.stringify($json.rawThemes) }] }) }}

