function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function list(value) {
  return Array.isArray(value) ? value : [];
}

function parseJson(value) {
  const source = String(value || '').replace(/```(?:json)?|```/gi, '').trim();
