  const tier = (tierWeight[b.sourceTier] || 0) - (tierWeight[a.sourceTier] || 0);
  if (tier) return tier;
  const right = Date.parse(b.publishedAt || '') || 0;
  const left = Date.parse(a.publishedAt || '') || 0;
  return right - left;
}

const initialCandidates = [
  ...list(initialRanked.themeAligned),
  ...list(initialRanked.emerging),
  ...list(initialRanked.watchlist),
]
  .sort((a, b) => Number(b?.scores?.total || 0) - Number(a?.scores?.total || 0))
  .filter((candidate, index, array) => {
    const key = clean(candidate?.topic || candidate?.proposedHeadline).toLowerCase();
    return key && array.findIndex((item) => clean(item?.topic || item?.proposedHeadline).toLowerCase() === key) === index;
  })
  .slice(0, 5);

const articleByUrl = new Map(combined.map((article) => [canonicalUrl(article.url), article]));
const recoveryEvidenceByTopic = initialCandidates.map((candidate) => {
  const topic = clean(candidate.topic || candidate.proposedHeadline);
  const cited = list(candidate.sources)
    .map((item) => articleByUrl.get(canonicalUrl(item.url)))
    .filter(Boolean);
  const recovered = combined.filter((article) =>
    article.origin === 'candidate_recovery' && article.recoveryForTopic === topic
  );
  const grouped = [];
  const groupedUrls = new Set();
  for (const article of [...cited, ...recovered].sort(compareArticles)) {
    const url = canonicalUrl(article.url);
    if (!url || groupedUrls.has(url)) continue;
    groupedUrls.add(url);
    grouped.push(article);
    if (grouped.length >= 12) break;
  }
  return {
    topic,
    proposedHeadline: clean(candidate.proposedHeadline),
    relatedMeetingThemes: list(candidate.relatedMeetingThemes),
    evidenceRecords: grouped,
  };
});

const discoveryRecords = combined
  .filter((article) => ['industry_discovery', 'discovery', 'authoritative_source', 'meeting_theme'].includes(article.origin))
  .sort(compareArticles)
  .slice(0, 55);

const foundationGroups = new Map();
for (const article of combined.filter((item) => item.origin === 'authoritative_foundation')) {
  const key = clean(article.relatedTheme) || 'Unmapped authoritative foundation';
  if (!foundationGroups.has(key)) foundationGroups.set(key, []);
  foundationGroups.get(key).push(article);
}

const foundationEvidenceByTheme = [...foundationGroups.entries()]
  .map(([relatedTheme, records]) => {
    const evidenceRecords = records.sort(compareArticles).slice(0, 10);
    const independentSourceFamilyCount = new Set(
      evidenceRecords.map((item) => sourceFamily(item.url)).filter(Boolean)
    ).size;
    return { relatedTheme, independentSourceFamilyCount, evidenceRecords };
  })
  .sort((a, b) =>
    b.independentSourceFamilyCount - a.independentSourceFamilyCount ||
    a.relatedTheme.localeCompare(b.relatedTheme)
  );


function claimRequiresPrimarySource(value) {
  return /\b(malware|ransomware|threat actor|attack campaign|cyberattack|breach|vulnerability|exploit|zero[- ]day|cve-|security advisory|product announcement|product launch)\b/i.test(clean(value));
}

const semanticStopWords = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'before', 'by', 'can', 'for',
  'from', 'how', 'in', 'into', 'is', 'it', 'new', 'of', 'on', 'or', 'our',
  'that', 'the', 'their', 'this', 'to', 'use', 'using', 'what', 'when', 'why',
  'with', 'your', 'ai', 'cyber', 'cybersecurity', 'security', 'technology',
  'enterprise', 'organization', 'organizations', 'management', 'manage',
  'risk', 'risks', 'system', 'systems', 'guidance', 'guide', 'framework',
  'operational', 'operations', 'leader', 'leaders', 'leadership', 'decision',
  'decisions', 'practice', 'practices', 'current', 'recent', 'official',
  'cisa', 'nist', 'microsoft',
]);

function semanticStem(value) {
  let token = clean(value).toLowerCase().replace(/[^a-z0-9-]/g, '');
  if (token.length > 6 && token.endsWith('ization')) token = token.slice(0, -7) + 'ize';
  else if (token.length > 6 && token.endsWith('ation')) token = token.slice(0, -5) + 'ate';
  else if (token.length > 5 && token.endsWith('ing')) token = token.slice(0, -3);
  else if (token.length > 5 && token.endsWith('ied')) token = token.slice(0, -3) + 'y';
  else if (token.length > 4 && token.endsWith('ed')) token = token.slice(0, -2);
  else if (token.length > 4 && token.endsWith('ies')) token = token.slice(0, -3) + 'y';
  else if (token.length > 4 && token.endsWith('s')) token = token.slice(0, -1);
  if (token.endsWith('ch')) return token;
  if (token.endsWith('tch')) return token;
  return token;
}

function semanticTokens(value) {
  return [...new Set(clean(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .split(/\s+/)
    .map(semanticStem)
    .filter((token) => token.length >= 3 && !semanticStopWords.has(token)))];
}

function semanticMatchTerms(anchor, article) {
  const anchorTerms = semanticTokens(anchor);
  const sourceTerms = new Set(semanticTokens(`${article.title || ''} ${article.description || ''}`));
  return anchorTerms.filter((term) => sourceTerms.has(term));
}

function distinctEligibleFamilies(records) {
  const selected = [];
  const seenFamilies = new Set();
  for (const article of [...records].sort(compareArticles)) {
    if (!['primary', 'credible_independent'].includes(article.sourceTier)) continue;
    const family = sourceFamily(article.url);
    if (!family || seenFamilies.has(family)) continue;
    seenFamilies.add(family);
    selected.push(article);
  }
  return selected;
}

const qualifiedEvidenceBundles = [];
const evidenceBundleDiagnostics = [];

function addEvidenceBundles({
  prefix,
  bundleType,
  relatedTopic,
  relatedTheme,
  relatedMeetingThemes,
  semanticAnchor,
  records,
  requiresPrimarySource,
  limit = 3,
}) {
  const eligible = distinctEligibleFamilies(records);
  const semanticTermsByUrl = new Map(eligible.map((article) => [
    canonicalUrl(article.url),
    semanticMatchTerms(semanticAnchor, article),
  ]));
  const semanticallyEligible = eligible.filter((article) =>
    list(semanticTermsByUrl.get(canonicalUrl(article.url))).length > 0
  );
  const primary = semanticallyEligible.filter((item) => item.sourceTier === 'primary');
  const credible = semanticallyEligible.filter((item) => item.sourceTier === 'credible_independent');
  const pairs = [];
  const seenPairs = new Set();

  function addPair(left, right) {
    if (!left || !right || pairs.length >= limit) return;
    const families = [sourceFamily(left.url), sourceFamily(right.url)].sort();
    if (!families[0] || families[0] === families[1]) return;
    const key = families.join('|');
    if (seenPairs.has(key)) return;
    const leftTerms = new Set(semanticTermsByUrl.get(canonicalUrl(left.url)) || []);
    const rightTerms = new Set(semanticTermsByUrl.get(canonicalUrl(right.url)) || []);
    const sharedSemanticTerms = [...leftTerms].filter((term) => rightTerms.has(term));
    if (!sharedSemanticTerms.length) return;
    seenPairs.add(key);
    const pair = [left, right];
    pair.sharedSemanticTerms = sharedSemanticTerms;
    pairs.push(pair);
  }

  for (const left of primary) {
    for (const right of credible) addPair(left, right);
  }
  for (let left = 0; left < primary.length; left++) {
    for (let right = left + 1; right < primary.length; right++) {
      addPair(primary[left], primary[right]);
    }
  }
  if (!requiresPrimarySource) {
    for (let left = 0; left < credible.length; left++) {
      for (let right = left + 1; right < credible.length; right++) {
        addPair(credible[left], credible[right]);
      }
    }
  }

  if (!pairs.length) {
    evidenceBundleDiagnostics.push({
      prefix,
      bundleType,
      relatedTopic,
      relatedTheme,
      semanticAnchor,
      requiresPrimarySource,
      eligibleSourceFamilyCount: eligible.length,
      semanticEligibleSourceFamilyCount: semanticallyEligible.length,
      primarySourceFamilyCount: primary.length,
      credibleIndependentSourceFamilyCount: credible.length,
      reason: requiresPrimarySource && !primary.length
        ? 'No primary source family was available'
        : 'Fewer than two qualifying independent source families were available',
    });
    return;
  }

  pairs.forEach((pair, index) => {
    const primarySourceFamilyCount = new Set(pair
      .filter((item) => item.sourceTier === 'primary')
      .map((item) => sourceFamily(item.url))).size;
    const credibleIndependentSourceFamilyCount = new Set(pair
      .filter((item) => item.sourceTier === 'credible_independent')
      .map((item) => sourceFamily(item.url))).size;
    const independentSourceFamilyCount = new Set(
      pair.map((item) => sourceFamily(item.url)).filter(Boolean)
    ).size;
    const primarySourceRequirementMet = !requiresPrimarySource || primarySourceFamilyCount >= 1;
    const qualified = independentSourceFamilyCount >= 2 && primarySourceRequirementMet;
    if (!qualified) return;

    qualifiedEvidenceBundles.push({
      bundleId: `${prefix}-${index + 1}`,
      bundleType,
      relatedTopic,
      relatedTheme,
      relatedMeetingThemes: list(relatedMeetingThemes),
      semanticAnchor,
      sharedSemanticTerms: list(pair.sharedSemanticTerms),
      requiresPrimarySource,
      primarySourceRequirementMet,
      primarySourceFamilyCount,
      credibleIndependentSourceFamilyCount,
      independentSourceFamilyCount,
      qualified,
      records: pair,
    });
  });
}

recoveryEvidenceByTopic.forEach((group, index) => {
  const candidate = initialCandidates.find((item) =>
    clean(item.topic || item.proposedHeadline) === group.topic
  ) || {};
  const claimText = `${group.topic} ${group.proposedHeadline} ${candidate.whyNow || ''} ${candidate.contentAngle || ''}`;
  addEvidenceBundles({
    prefix: `candidate-${index + 1}`,
    bundleType: 'candidate_recovery',
    relatedTopic: group.topic,
    relatedTheme: '',
    relatedMeetingThemes: group.relatedMeetingThemes,
    semanticAnchor: claimText,
    records: group.evidenceRecords,
    requiresPrimarySource: claimRequiresPrimarySource(claimText),
  });
});

foundationEvidenceByTheme.forEach((group, index) => {
  addEvidenceBundles({
    prefix: `foundation-${index + 1}`,
    bundleType: 'durable_foundation',
    relatedTopic: '',
    relatedTheme: group.relatedTheme,
    relatedMeetingThemes: [group.relatedTheme],
    semanticAnchor: group.relatedTheme,
    records: group.evidenceRecords.filter((item) => item.sourceTier === 'primary'),
    requiresPrimarySource: false,
    limit: 2,
  });
});

const discoveryGroups = new Map();
for (const article of discoveryRecords) {
  const key = clean(article.relatedTheme) || clean(article.possibleIndustry) || 'Unmapped discovery';
  if (!discoveryGroups.has(key)) discoveryGroups.set(key, []);
  discoveryGroups.get(key).push(article);
}

[...discoveryGroups.entries()].slice(0, 12).forEach(([query, records], index) => {
  addEvidenceBundles({
    prefix: `discovery-${index + 1}`,
    bundleType: 'industry_discovery',
    relatedTopic: query,
    relatedTheme: query,
    relatedMeetingThemes: [],
    semanticAnchor: query,
    records,
    requiresPrimarySource: claimRequiresPrimarySource(query),
    limit: 2,
  });
});

const selectedUrls = new Set();
const articles = [];
for (const article of [
  ...qualifiedEvidenceBundles.flatMap((bundle) => bundle.records),
  ...recoveryEvidenceByTopic.flatMap((group) => group.evidenceRecords),
  ...foundationEvidenceByTheme.flatMap((group) => group.evidenceRecords),
  ...discoveryRecords,
]) {
  const url = canonicalUrl(article.url);
  if (!url || selectedUrls.has(url)) continue;
  selectedUrls.add(url);
  articles.push(article);
}

if (!articles.length) throw new Error('No usable articles remained after evidence recovery.');

return [{
  json: {
    workflowVersion: '4.7',
    sourceThemeFile: source.sourceThemeFile,
    sourceThemeDate: source.sourceThemeDate,
    consolidatedThemes: source.consolidatedThemes,
    initialArticleCount: list(source.articles).length,
    recoveryQueryCount: recoveryResponses.length,
    recoveryResultCount,
    recoveryArticleCount: articles.filter((item) =>
      item.origin === 'candidate_recovery' || item.origin === 'industry_discovery'
    ).length,
    authoritativeFoundationCount: articles.filter((item) => item.origin === 'authoritative_foundation').length,
    sourceTierCounts: {
      primary: articles.filter((item) => item.sourceTier === 'primary').length,
      credible_independent: articles.filter((item) => item.sourceTier === 'credible_independent').length,
      other: articles.filter((item) => item.sourceTier === 'other').length,
    },
    initialSourceTierCounts: source.initialSourceTierCounts || {},
    recoveryQueryKindCounts: queryItems.reduce((counts, item) => {
      const key = clean(item.recoveryKind || 'unknown');
      counts[key] = (counts[key] || 0) + 1;
      return counts;
    }, {}),
    articleCount: articles.length,
    initialCandidates,
    recoveryEvidenceByTopic,
    foundationEvidenceByTheme,
    discoveryRecords,
    qualifiedEvidenceBundleCount: qualifiedEvidenceBundles.length,
    qualifiedEvidenceBundles,
    evidenceBundleDiagnostics,
    articles,
  },
}];

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

const dateParts = Object.fromEntries(
  new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    year: 'numeric', month: '2-digit', day: '2-digit',
  })
    .formatToParts(new Date())
    .filter((part) => part.type !== 'literal')
    .map((part) => [part.type, part.value])
);
const freshness = `2010-01-01to${dateParts.year}-${dateParts.month}-${dateParts.day}`;
const themes = $('Parse Consolidated Themes').all().map((item) => clean(item.json.theme));
const definitions = [];
const seen = new Set();

function add(category, query, relatedTheme = '') {
  const key = clean(query).toLowerCase();
  if (!key || seen.has(key)) return;
  seen.add(key);
  definitions.push({ category, query: clean(query), relatedTheme, freshness });
}

for (const theme of themes.slice(0, 8)) {
  for (const domain of ['nist.gov', 'cisa.gov']) {
    add(`Foundation for ${theme} from ${domain}`, `${theme} guidance framework site:${domain}`, theme);
  }
}

add('NIST AI governance', 'AI Risk Management Framework governance site:nist.gov', 'AI Governance and Policy Frameworks');
add('CISA resilience', 'cyber resilience recovery planning guidance site:cisa.gov', 'Enterprise Infrastructure Resilience and Recovery');
add('NIST zero trust', 'zero trust architecture network segmentation site:nist.gov', 'Network Segmentation and Traffic Analysis');
add('CISA secure by design', 'secure by design exposure management site:cisa.gov', 'Unified Exposure Management for IT and OT');
add('NIST identity', 'digital identity guidelines secure remote access site:nist.gov', 'Secure Remote Access and Identity Patterns');
add('NIST asset management', 'asset lifecycle cybersecurity framework site:nist.gov', 'Asset Lifecycle Management and Compliance');

return definitions.map((definition) => ({ json: definition }));

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

const output = [];
const queries = $('Create Authoritative Foundation Queries').all().map((item) => item.json);
const responses = $input.all();

for (let index = 0; index < responses.length; index++) {
  const response = responses[index].json;
  const metadata = queries[index] || {};
  const results = Array.isArray(response.web?.results)
    ? response.web.results
    : Array.isArray(response.results) ? response.results : [];

  for (const result of results) {
    output.push({
      json: {
        origin: 'authoritative_foundation',
        relatedTheme: clean(metadata.relatedTheme),
        title: clean(result.title),
        url: clean(result.url),
        description: clean(result.description || result.snippet),
        publishedAt: clean(result.page_age || result.age),
        age: clean(result.age),
        publisher: clean(result.profile?.long_name || result.meta_url?.hostname || result.meta_url?.netloc),
      },
    });
  }
}

return output;

